/* Runs the machine on fake hardware and prints every log line.
 * Usage: build/sim <run_ms> [EVENT ...]
 * The listed events are sent at t = 0, in order. */
#include <stdio.h>
#include <stdlib.h>

#include "gen/fake.h"
#include "gen/hal.h"
#include "gen/machine.h"

static sensor_probe_t probe;

int main(int argc, char **argv) {
    uint64_t run_ms = argc > 1 ? strtoull(argv[1], NULL, 10) : 15000;
    sensor_safe_hal_t hal = sensor_safe_hal(sensor_fake_hal(&probe));
    sensor_machine_t m;
    sensor_start(&m, &hal);
    for (int i = 2; i < argc; i++) {
        sensor_event_t e;
        if (sensor_event_from_name(argv[i], &e)) sensor_send(&m, e, &hal);
        else fprintf(stderr, "unknown event %s\n", argv[i]);
    }
    int printed = 0;
    for (uint64_t t = 0; t <= run_ms; t += 10) {
        probe.now_ms = t;
        sensor_tick(&m, &hal);
        for (; printed < probe.n_logs; printed++)
            printf("%7.1fs  %s\n", (double)probe.logs[printed].at / 1000.0, probe.logs[printed].msg);
    }
    printf("final state: %s\n", sensor_state_id(m.state));
    return 0;
}
